'use strict';

const fs = require('node:fs');
const path = require('node:path');
const { StringDecoder } = require('node:string_decoder');

const { writeFileAtomicIfAbsent } = require('../atomic-write');
const { validateAgainstSchema } = require('../../contracts/schema-validator');
const { resolveWorkflowArtifactDir } = require('../../verification/artifact-paths');
const {
  resolveTargetRepoRoot,
  validateOutputContainment,
  validateRepoRelativeField,
} = require('./target-repo');

const RUN_SUMMARY_SCHEMA_VERSION = 'verification-run-summary.v1';
const RUN_SUMMARY_SCHEMA_PATH = path.join(__dirname, '..', '..', '..', 'docs', 'contracts', 'verification', 'verification-run-summary.schema.json');
const DEFAULT_WORKFLOW = 'spec-work';
const ALLOWED_WORKFLOWS = new Set(['spec-work', 'spec-debug', 'spec-code-review']);
const SAFE_ID_PATTERN = /^[A-Za-z0-9][A-Za-z0-9._-]{0,80}$/;
const ALLOWED_INPUT_FIELDS = new Set(['profile', 'checks']);
const ALLOWED_PROFILE_FIELDS = new Set(['source', 'name', 'path']);
const ALLOWED_CHECK_FIELDS = new Set([
  'id',
  'service',
  'command',
  'status',
  'exit_code',
  'ran',
  'required_tools',
  'missing_tools',
  'log_path',
  'reason_code',
  'redaction_status',
]);
const ALLOWED_STATUSES = new Set(['passed', 'failed', 'not-run', 'degraded']);
const ALLOWED_REDACTION_STATUSES = new Set(['redacted', 'none-required']);
const LOG_SCAN_CHUNK_BYTES = 64 * 1024;
const LOG_SCAN_OVERLAP_CHARS = 4 * 1024;
// URL credential/query 模式允许无界非空白前缀。跨 chunk 保留未闭合 URL 候选，
// 超出有界检查预算后 fail closed，不依赖固定 overlap 侥幸覆盖。
const LOG_SCAN_MAX_URL_CANDIDATE_CHARS = 64 * 1024;

let cachedSchema = null;

function runCli(argv) {
  const args = Array.isArray(argv) ? [...argv] : [];
  const subcommand = args[0];

  if (['--help', '-h'].includes(subcommand)
    || (['record', 'read'].includes(subcommand) && ['--help', '-h'].includes(args[1]))) {
    writeJson({
      status: 'help',
      usage: [
        'spec-first internal verification-run-summary record --input <input.json> --run-id <run-id> --target-repo <repo> [--workflow <workflow>] [--json]',
        'spec-first internal verification-run-summary read --run-summary-ref <repo-relative-path> --target-repo <repo> [--json]',
      ],
      workflows: [...ALLOWED_WORKFLOWS],
      input_fields: [...ALLOWED_INPUT_FIELDS],
      check_fields: [...ALLOWED_CHECK_FIELDS],
      statuses: [...ALLOWED_STATUSES],
      redaction_statuses: [...ALLOWED_REDACTION_STATUSES],
      notes: [
        '示例为尚未执行的检查，不是验证证据。按实际命令结果填写，不得直接改为 passed。',
        'reason_code 为具体原因字符串，不是固定枚举；schedulable 与 missing_dependency 仅用于 not-run。检查实际执行后应同步改为实际原因（例如 executed），不能沿用示例的 schedulable。',
        '已执行检查必须包含真实退出码与脱敏日志；log_path 为仓库相对路径，位于 .spec-first/workflows/<workflow>/<workspace-slug>/<run-id>/logs/。',
        '输入只包含 profile 和 checks；schema_version、generated_at 和输出路径由 writer 生成。',
      ],
      input_example: {
        profile: { source: 'local', name: 'example', path: null },
        checks: [{
          id: 'example-check', service: 'node', command: 'node verify.cjs',
          status: 'not-run', exit_code: null, ran: false,
          required_tools: ['node'], missing_tools: [], log_path: null,
          reason_code: 'schedulable', redaction_status: 'none-required',
